<script setup lang="ts">
import {ref,onMounted} from 'vue'
const props=defineProps<{request:(path:string,body?:any,method?:string)=>Promise<any>}>()
const rows=ref<any[]>([]),count=ref(0),page=ref(1),state=ref('open'),error=ref(''),busy=ref(false),resolution=ref(''),selected=ref<any>(null)
async function load(){busy.value=true;error.value='';try{const data=await props.request(`follow-ups/?state=${state.value}&page=${page.value}`);rows.value=data.results;count.value=data.count}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function close(){busy.value=true;error.value='';try{await props.request(`follow-ups/${selected.value.id}/close/`,{resolution:resolution.value});selected.value=null;resolution.value='';await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><section><h3>Tâches de suivi</h3><p>Les tâches ouvertes restent signalées jusqu’à une clôture justifiée. L’échéance initiale est fixée à 24 heures, à confirmer avec le client.</p><p v-if="error" role="alert">{{error}}</p><label>Afficher<select v-model="state" @change="page=1;load()"><option value="open">Ouvertes</option><option value="closed">Clôturées</option><option value="all">Toutes</option></select></label><button class="secondary" :disabled="busy" @click="load">Actualiser</button><article v-for="row in rows" :key="row.id"><h4>{{row.contact_name||'Prospect'}} · RDV {{row.appointment_id}}</h4><p>{{row.reason}}</p><p>Priorité : {{row.priority}} · Échéance : {{new Date(row.due_at).toLocaleString('fr-FR')}}</p><p v-if="row.closed_at">Clôturée : {{row.resolution}}</p><button v-else class="secondary" :disabled="busy" @click="selected=row;resolution=''">Clôturer avec justification</button></article><p v-if="!rows.length">Aucune tâche.</p><p>{{count}} tâche(s) · page {{page}}</p><button class="secondary" :disabled="busy||page===1" @click="page--;load()">Précédent</button><button class="secondary" :disabled="busy||page*25>=count" @click="page++;load()">Suivant</button><form v-if="selected" @submit.prevent="close"><label>Justification de clôture<textarea v-model="resolution" required maxlength="3000"></textarea></label><button class="primary" :disabled="busy">Confirmer la clôture</button><button type="button" class="secondary" @click="selected=null">Annuler</button></form></section></template>
